select 'function' kind,n.nspname||'.'||p.proname key,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('apply_sponsorship_allocations','assert_sponsorship_allocation_valid','assign_sponsorship_animal_with_audit','log_animal_mutation','record_sponsorship_payment_proof','reverse_sponsorship_allocation_with_audit','review_sponsorship_payment_proof','set_animal_catalog_membership_defaults')
union all select 'column',c.relname||'.'||a.attname,format_type(a.atttypid,a.atttypmod)||' notnull='||a.attnotnull||' default='||coalesce(pg_get_expr(ad.adbin,ad.adrelid),'') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where n.nspname='public' and c.relname in ('animals','donation','payment','webhook_event') and a.attnum>0 and not a.attisdropped
union all select 'trigger',c.relname||'.'||t.tgname,pg_get_triggerdef(t.oid,true) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal
union all select 'constraint',c.relname||'.'||x.conname,pg_get_constraintdef(x.oid,true) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('animals','donation','payment','webhook_event')
union all select 'index',tablename||'.'||indexname,indexdef from pg_indexes where schemaname='public' and tablename in ('animals','donation','payment','webhook_event')
union all select 'policy',tablename||'.'||policyname,jsonb_build_array(permissive,roles,cmd,qual,with_check)::text from pg_policies where schemaname='public' and tablename='adoption_applications' order by kind,key